// SPEC-DERIVED-PHASE3B  HALT #21 (UpdaterStateMachine tests)
using System; using Microsoft.VisualStudio.TestTools.UnitTesting; using TaskTree.Core.Enums; using TaskTree.Modules.AutoUpdater; using TaskTree.TestSupport;
namespace TaskTree.Modules.AutoUpdater.Tests{[TestClass]public class UpdaterStateMachineTests{[TestMethod]public void Constructor_DefaultState_IsIdle(){Assert.AreEqual(UpdaterState.Idle,new UpdaterStateMachine(new FakeClock()).Current);}[TestMethod]public void Transition_HappyPath_Applied(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Downloading);m.TransitionTo(UpdaterState.Verifying);m.TransitionTo(UpdaterState.Staging);m.TransitionTo(UpdaterState.Applying);m.TransitionTo(UpdaterState.Applied);Assert.AreEqual(UpdaterState.Applied,m.Current);}[TestMethod]public void Transition_CheckingToIdle_NoUpdate(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Idle);Assert.AreEqual(UpdaterState.Idle,m.Current);}[TestMethod]public void Transition_VerifyingToFailed(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Downloading);m.TransitionTo(UpdaterState.Verifying);m.TransitionTo(UpdaterState.Failed);Assert.AreEqual(UpdaterState.Failed,m.Current);}[TestMethod]public void Transition_ApplyingToFailed(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Downloading);m.TransitionTo(UpdaterState.Verifying);m.TransitionTo(UpdaterState.Staging);m.TransitionTo(UpdaterState.Applying);m.TransitionTo(UpdaterState.Failed);Assert.AreEqual(UpdaterState.Failed,m.Current);}[TestMethod]public void Transition_FailedToIdle(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Downloading);m.TransitionTo(UpdaterState.Verifying);m.TransitionTo(UpdaterState.Failed);m.TransitionTo(UpdaterState.Idle);Assert.AreEqual(UpdaterState.Idle,m.Current);}[TestMethod]public void Transition_AppliedToIdle(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.TransitionTo(UpdaterState.Downloading);m.TransitionTo(UpdaterState.Verifying);m.TransitionTo(UpdaterState.Staging);m.TransitionTo(UpdaterState.Applying);m.TransitionTo(UpdaterState.Applied);m.TransitionTo(UpdaterState.Idle);Assert.AreEqual(UpdaterState.Idle,m.Current);}[TestMethod]public void Transition_Invalid_Throws(){Assert.ThrowsException<InvalidOperationException>(()=>new UpdaterStateMachine(new FakeClock()).TransitionTo(UpdaterState.Downloading));}[TestMethod]public void Reset_ToIdle(){var m=new UpdaterStateMachine(new FakeClock());m.TransitionTo(UpdaterState.Checking);m.Reset();Assert.AreEqual(UpdaterState.Idle,m.Current);}[TestMethod]public void StateChanged_Fires(){var m=new UpdaterStateMachine(new FakeClock());var fired=false;m.StateChanged+=(s,e)=>fired=e.Previous==UpdaterState.Idle&&e.Current==UpdaterState.Checking;m.TransitionTo(UpdaterState.Checking);Assert.IsTrue(fired);}}}
